script:
frappe.ui.form.on('Client Branch', {
    refresh: function(frm) {

        set_client_branch_contact_filters(frm);

        if (!frm.is_new()) {
            refresh_branch_inventory(frm);
        }

        add_create_service_ticket_button(frm);
        add_plan_intervention_button(frm);
        add_get_directions_button(frm);
    }
});

function set_client_branch_contact_filters(frm) {

    frm.set_query('custom_contact', 'custom_branch_contacts', function() {
        return {
            filters: [
                ['Contact', 'custom_contact_scope', '=', 'Branch Level'],
                ['Contact', 'custom_client_branch', '=', frm.doc.name],
                ['Dynamic Link', 'link_doctype', '=', 'Customer'],
                ['Dynamic Link', 'link_name', '=', frm.doc.custom_parent_customer]
            ]
        };
    });

    frm.set_query('custom_contact', 'custom_head_office_contacts', function() {
        return {
            filters: [
                ['Contact', 'custom_contact_scope', '=', 'Head Office Level'],
                ['Dynamic Link', 'link_doctype', '=', 'Customer'],
                ['Dynamic Link', 'link_name', '=', frm.doc.custom_parent_customer]
            ]
        };
    });
}

frappe.ui.form.on('Client Branch Contact', {
    custom_contact: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.custom_contact) {
            return;
        }

        frappe.db.get_doc('Contact', row.custom_contact).then(function(contact) {

            let primary_email = '';
            let primary_phone = '';

            // =========================
            // EMAIL
            // =========================

            if (contact.email_ids && contact.email_ids.length > 0) {

                let primary_email_row = contact.email_ids.find(function(e) {
                    return e.is_primary === 1;
                });

                if (primary_email_row) {
                    primary_email = primary_email_row.email_id;
                }
                else {
                    primary_email = contact.email_ids[0].email_id;
                }
            }

            // =========================
            // PHONE
            // =========================

            if (contact.phone_nos && contact.phone_nos.length > 0) {

                let primary_phone_row = contact.phone_nos.find(function(p) {
                    return (
                        p.is_primary_mobile === 1 ||
                        p.is_primary_phone === 1
                    );
                });

                if (primary_phone_row) {
                    primary_phone = primary_phone_row.phone;
                }
                else {
                    primary_phone = contact.phone_nos[0].phone;
                }
            }

            // =========================
            // UPDATE CHILD TABLE
            // =========================

            frappe.model.set_value(
                cdt,
                cdn,
                'custom_contact_role',
                contact.designation || ''
            );

            frappe.model.set_value(
                cdt,
                cdn,
                'custom_email',
                primary_email || ''
            );

            frappe.model.set_value(
                cdt,
                cdn,
                'custom_phone',
                primary_phone || ''
            );

        });
    }
});


/* =========================
   BRANCH INVENTORY
========================= */

function refresh_branch_inventory(frm) {

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Installed Equipment',
            filters: {
                custom_branch: frm.doc.name
            },
            fields: [
                'name',
                'custom_asset_id',
                'custom_client_asset_code',
                'custom_display_name',
                'custom_model',
                'custom_make',
                'custom_asset_category',
                'custom_asset_status'
            ],
            limit_page_length: 500
        },

        callback: function(r) {

            frm.clear_table('custom_branch_inventory');

            (r.message || []).forEach(function(asset) {

                let row = frm.add_child('custom_branch_inventory');

                row.custom_asset_id = asset.name;
                row.custom_serial_number = asset.custom_asset_id;
                row.custom_model = asset.custom_model;
                row.custom_make = asset.custom_make;
                row.custom_category = asset.custom_asset_category;
                row.custom_status = asset.custom_asset_status;

                if ('custom_client_asset_code' in row) {
                    row.custom_client_asset_code =
                        asset.custom_client_asset_code;
                }

                if ('custom_display_name' in row) {
                    row.custom_display_name =
                        asset.custom_display_name;
                }

            });

            frm.refresh_field('custom_branch_inventory');

        }
    });
}

function add_create_service_ticket_button(frm) {
    if (frm.is_new()) {
        return;
    }

    frm.add_custom_button(__('Create Service Ticket'), function() {

        let ticket_subject =
            'Service Request: ' +
            (frm.doc.custom_branch || frm.doc.name);

        frappe.call({
            method: 'frappe.client.insert',

            args: {
                doc: {
                    doctype: 'Service Ticket',
                    custom_subject: ticket_subject,
                    custom_customer: frm.doc.custom_parent_customer,
                    custom_client_branch: frm.doc.name,
                    custom_request_type: 'General Request',
                    custom_ticket_status: 'Open',
                    custom_client_status: 'Submitted'
                }
            },

            callback: function(r) {

                if (r && r.message) {

                    frappe.set_route(
                        'Form',
                        'Service Ticket',
                        r.message.name
                    );
                }
            }
        });

    }, __('Actions'));
}


function add_plan_intervention_button(frm) {

    if (frm.is_new()) {
        return;
    }

    frm.add_custom_button(__('Plan Intervention'), function() {

        frappe.model.with_doctype('Tech Planning', function() {

            let p =
                frappe.model.get_new_doc(
                    'Tech Planning'
                );

            p.custom_parent_customer =
                frm.doc.custom_parent_customer;

            p.custom_branch =
                frm.doc.name;

            p.custom_asset = '';

            p.custom_planning_status =
                'Draft';

            frappe.set_route(
                'Form',
                'Tech Planning',
                p.name
            );

        });

    }, __('Actions'));
}

function add_get_directions_button(frm) {
    if (frm.is_new()) {
        return;
    }

    frm.add_custom_button(__('Get Directions'), function() {

        if (!frm.doc.custom_address) {
            frappe.msgprint(__('No address found for this branch.'));
            return;
        }

        let maps_url =
            'https://www.google.com/maps/search/?api=1&query=' +
            encodeURIComponent(frm.doc.custom_address);

        window.open(maps_url, '_blank');

    }, __('Actions'));
}

frappe.ui.form.on('Maintenance Item', {
    setup: function(frm) {
        // Apply strict filters to the ERP Item Link field
        frm.set_query('custom_erp_item', function() {
            return {
                filters: [
                    ['Item', 'is_stock_item', '=', 1],      // Must be a physical product
                    ['Item', 'disabled', '=', 0],          // Must be active
                    ['Item', 'item_group', 'not in', [
                        'Services', 
                        'Accessories', 
                        'Cables', 
                        'Consumables'
                    ]], // Exclude non-core maintenance items
                    ['Item', 'is_fixed_asset', '=', 0]     // Optional: Exclude internal Gotech assets
                ]
            };
        });
    }
});

frappe.ui.form.on('Customer', {
    refresh: function(frm) {
        // --- 1. GLOBAL ASSET INVENTORY REFRESH ---
        if (!frm.is_new()) {
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Installed Equipment',
                    filters: {
                        'custom_parent_customer': frm.doc.name 
                    },
                    fields: [
                        'name', 
                        'custom_asset_id',         // Serial Number from Registry
                        'custom_model', 
                        'custom_make', 
                        'custom_asset_category',
                        'custom_branch'            // Branch ID
                    ]
                },
                callback: function(r) {
                    if (r.message) {
                        // Clear existing rows to prevent duplicates on refresh
                        frm.clear_table('custom_total_assets');

                        r.message.forEach(asset => {
                            let row = frm.add_child('custom_total_assets');

                            // Map Registry data to Customer Table columns
                            row.custom_asset_id = asset.name;                 // Link to Doc
                            row.custom_serial_number = asset.custom_asset_id; // Physical Serial
                            row.custom_model = asset.custom_model;
                            row.custom_make = asset.custom_make;
                            row.custom_category = asset.custom_asset_category;

                            // Populate the Branch column (Logic for No-Branch scenarios)
                            row.custom_branch_display = asset.custom_branch ? asset.custom_branch : "Main / HQ";
                        });

                        // Refresh UI to show data
                        frm.refresh_field('custom_total_assets');

                        // --- 2. SECURITY: DISABLE MANUAL TABLE EDITS ---
                        // Disables "Add Row" and "Delete" buttons via script
                        frm.set_df_property('custom_total_assets', 'read_only', 1);
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Maintenance Contract', {
    setup(frm) {
        set_contract_filters(frm);
    },

    refresh(frm) {
        set_contract_filters(frm);
        toggle_consumption_fields(frm);
        toggle_transport_fields(frm);
        toggle_remote_ticket_limit(frm);
        toggle_carryover_fields(frm);
        calculate_contract_duration(frm);
        calculate_days_remaining(frm);
        update_mc_banner(frm);
    },

    custom_customer(frm) {
        set_contract_filters(frm);
    },

    custom_consumption_type(frm) {
        toggle_consumption_fields(frm);
    },

    custom_includes_transport(frm) {
        toggle_transport_fields(frm);
    },

    custom_start_date(frm) {
        calculate_contract_duration(frm);
        calculate_days_remaining(frm);
        calculate_period_reset_date(frm);
    },

    custom_end_date(frm) {
        calculate_contract_duration(frm);
        calculate_days_remaining(frm);
    },

    custom_status(frm) {
        update_mc_banner(frm);
    },

    custom_remote_tickets_included(frm) {
        toggle_remote_ticket_limit(frm);
        calculate_remote_tickets_remaining(frm);
    },

    custom_remote_tickets_limit(frm) {
        calculate_remote_tickets_remaining(frm);
    },

    custom_remote_tickets_used(frm) {
        calculate_remote_tickets_remaining(frm);
    },

    custom_onsite_visits_included(frm) {
        calculate_onsite_visits_remaining(frm);
    },

    custom_onsite_visits_used(frm) {
        calculate_onsite_visits_remaining(frm);
    },

    custom_consumption_period(frm) {
        calculate_period_reset_date(frm);
    },

    custom_allows_carryover(frm) {
        toggle_carryover_fields(frm);
    }
});

frappe.ui.form.on('Contract Equipment', {
    custom_branch(frm, cdt, cdn) {
        frappe.model.set_value(cdt, cdn, 'custom_equipment', '');
        frappe.model.set_value(cdt, cdn, 'custom_client_asset_code', '');
        frappe.model.set_value(cdt, cdn, 'custom_serial_number', '');
        set_contract_filters(frm);
    },

    custom_equipment(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row.custom_equipment) {
            frappe.model.set_value(cdt, cdn, 'custom_client_asset_code', '');
            frappe.model.set_value(cdt, cdn, 'custom_serial_number', '');
            return;
        }

        frappe.db.get_value('Installed Equipment', row.custom_equipment, [
            'custom_client_asset_code',
            'custom_asset_id',
            'custom_branch',
            'custom_parent_customer'
        ], function(r) {
            if (!r) return;

            if (frm.doc.custom_customer && r.custom_parent_customer !== frm.doc.custom_customer) {
                frappe.model.set_value(cdt, cdn, 'custom_equipment', '');
                frappe.model.set_value(cdt, cdn, 'custom_client_asset_code', '');
                frappe.model.set_value(cdt, cdn, 'custom_serial_number', '');
                frappe.msgprint(__('Selected equipment does not belong to this customer.'));
                return;
            }

            frappe.model.set_value(cdt, cdn, 'custom_client_asset_code', r.custom_client_asset_code || '');
            frappe.model.set_value(cdt, cdn, 'custom_serial_number', r.custom_asset_id || '');

            if (!row.custom_branch && r.custom_branch) {
                frappe.model.set_value(cdt, cdn, 'custom_branch', r.custom_branch);
            }
        });
    }
});

/* ═══════════════════════════════════════════════════════════
   FILTERS & QUERIES
═══════════════════════════════════════════════════════════ */

function set_contract_filters(frm) {
    frm.set_query('custom_branch', 'custom_covered_branches', function() {
        if (!frm.doc.custom_customer) return {};

        return {
            filters: [
                ['Client Branch', 'custom_parent_customer', '=', frm.doc.custom_customer]
            ]
        };
    });

    frm.set_query('custom_branch', 'custom_covered_equipment', function() {
        if (!frm.doc.custom_customer) return {};

        return {
            filters: [
                ['Client Branch', 'custom_parent_customer', '=', frm.doc.custom_customer]
            ]
        };
    });

    frm.set_query('custom_equipment', 'custom_covered_equipment', function(doc, cdt, cdn) {
        let row = locals[cdt][cdn];
        let filters = [];

        if (frm.doc.custom_customer) {
            filters.push(['Installed Equipment', 'custom_parent_customer', '=', frm.doc.custom_customer]);
        }

        if (row && row.custom_branch) {
            filters.push(['Installed Equipment', 'custom_branch', '=', row.custom_branch]);
        }

        return { filters: filters };
    });
}

/* ═══════════════════════════════════════════════════════════
   CONSUMPTION FIELDS VISIBILITY
═══════════════════════════════════════════════════════════ */

function toggle_consumption_fields(frm) {
    const type = frm.doc.custom_consumption_type;

    const ticket_fields = [
        'custom_included_tickets',
        'custom_used_tickets',
        'custom_remaining_tickets'
    ];

    const hour_fields = [
        'custom_included_hours',
        'custom_used_hours',
        'custom_remaining_hours',
        'custom_min_billable_minutes',
        'custom_rounding_increment'
    ];

    if (type === 'Ticket-based') {
        ticket_fields.forEach(f => frm.set_df_property(f, 'hidden', 0));
        hour_fields.forEach(f => frm.set_df_property(f, 'hidden', 1));
    } else if (type === 'Hour-based') {
        ticket_fields.forEach(f => frm.set_df_property(f, 'hidden', 1));
        hour_fields.forEach(f => frm.set_df_property(f, 'hidden', 0));
    } else {
        ticket_fields.forEach(f => frm.set_df_property(f, 'hidden', 1));
        hour_fields.forEach(f => frm.set_df_property(f, 'hidden', 1));
    }

    frm.refresh_fields();
}

function toggle_transport_fields(frm) {
    const includes_transport = frm.doc.custom_includes_transport;

    ['custom_transport_item', 'custom_transport_rate'].forEach(f => {
        frm.set_df_property(f, 'hidden', !includes_transport);
        frm.set_df_property(f, 'reqd', includes_transport);
    });

    frm.refresh_fields();
}

/* ═══════════════════════════════════════════════════════════
   DURATION & DAYS CALCULATIONS
═══════════════════════════════════════════════════════════ */

function calculate_contract_duration(frm) {
    if (!frm.doc.custom_start_date || !frm.doc.custom_end_date) return;

    let start = moment(frm.doc.custom_start_date);
    let end = moment(frm.doc.custom_end_date);

    if (end.isBefore(start)) {
        frappe.msgprint(__('End date must be after start date'));
        frm.set_value('custom_end_date', '');
        return;
    }

    let years = end.diff(start, 'years', true);
    frm.set_value('custom_duration_years', Math.round(years));
}

function calculate_days_remaining(frm) {
    if (!frm.doc.custom_end_date) return;

    let today = moment();
    let end_date = moment(frm.doc.custom_end_date);
    let days = end_date.diff(today, 'days');

    frm.set_value('custom_days_remaining', days);

    // Auto-expire if past end date
    if (days < 0 && frm.doc.custom_status !== 'Expired') {
        frm.set_value('custom_status', 'Expired');
        frappe.show_alert({
            message: __('Contract has expired'),
            indicator: 'red'
        });
    }
}

/* ═══════════════════════════════════════════════════════════
   REMOTE TICKETS TRACKING
═══════════════════════════════════════════════════════════ */

function toggle_remote_ticket_limit(frm) {
    let show = frm.doc.custom_remote_tickets_included === 'Limited';

    if (frm.fields_dict.custom_remote_tickets_limit) {
        frm.set_df_property('custom_remote_tickets_limit', 'hidden', !show);
        frm.set_df_property('custom_remote_tickets_limit', 'reqd', show);
    }

    frm.refresh_fields();
}

function calculate_remote_tickets_remaining(frm) {
    if (frm.doc.custom_remote_tickets_included === 'Unlimited') {
        return;
    }

    let limit = frm.doc.custom_remote_tickets_limit || 0;
    let used = frm.doc.custom_remote_tickets_used || 0;
    let remaining = limit - used;

    frm.set_value('custom_remote_tickets_remaining', remaining);

    if (remaining < 0) {
        frappe.show_alert({
            message: __('Remote ticket limit exceeded by ' + Math.abs(remaining)),
            indicator: 'red'
        });
    } else if (remaining <= 2) {
        frappe.show_alert({
            message: __('Only ' + remaining + ' remote tickets remaining'),
            indicator: 'orange'
        });
    }
}

/* ═══════════════════════════════════════════════════════════
   ONSITE VISITS TRACKING
═══════════════════════════════════════════════════════════ */

function calculate_onsite_visits_remaining(frm) {
    let included = frm.doc.custom_onsite_visits_included || 0;
    let used = frm.doc.custom_onsite_visits_used || 0;
    let remaining = included - used;

    frm.set_value('custom_onsite_visits_remaining', remaining);

    if (remaining < 0) {
        frappe.show_alert({
            message: __('Onsite visits limit exceeded by ' + Math.abs(remaining) + '. Additional visits will be charged.'),
            indicator: 'red'
        });
    } else if (remaining <= 1 && remaining > 0) {
        frappe.show_alert({
            message: __('Only ' + remaining + ' onsite visit(s) remaining'),
            indicator: 'orange'
        });
    }
}

/* ═══════════════════════════════════════════════════════════
   CONSUMPTION PERIOD & RESET
═══════════════════════════════════════════════════════════ */

function calculate_period_reset_date(frm) {
    if (!frm.doc.custom_start_date || !frm.doc.custom_consumption_period) return;

    let start = moment(frm.doc.custom_start_date);
    let reset_date;

    switch(frm.doc.custom_consumption_period) {
        case 'Monthly':
            reset_date = start.add(1, 'month').format('YYYY-MM-DD');
            break;
        case 'Quarterly':
            reset_date = start.add(3, 'months').format('YYYY-MM-DD');
            break;
        case 'Bi-annual':
            reset_date = start.add(6, 'months').format('YYYY-MM-DD');
            break;
        case 'Annual':
            reset_date = start.add(1, 'year').format('YYYY-MM-DD');
            break;
        default:
            reset_date = null;
    }

    if (reset_date) {
        frm.set_value('custom_period_reset_date', reset_date);
    }
}

/* ═══════════════════════════════════════════════════════════
   CARRYOVER RULES
═══════════════════════════════════════════════════════════ */

function toggle_carryover_fields(frm) {
    let show = frm.doc.custom_allows_carryover;

    ['custom_carryover_max_percent', 'custom_carryover_hours_available', 'custom_carryover_visits_available'].forEach(field => {
        if (frm.fields_dict[field]) {
            frm.set_df_property(field, 'hidden', !show);
        }
    });

    frm.refresh_fields();
}

/* ═══════════════════════════════════════════════════════════
   BANNER & STATUS
═══════════════════════════════════════════════════════════ */

function update_mc_banner(frm) {
    let status = frm.doc.custom_status || 'Draft';
    let days_remaining = frm.doc.custom_days_remaining || 0;

    let indicator = 'gray';
    let message = '';

    if (status === 'Draft') {
        indicator = 'gray';
        message = 'Contract Draft - Not Yet Active';
    } else if (status === 'Active') {
        if (days_remaining < 0) {
            indicator = 'red';
            message = '🔴 Contract Expired';
        } else if (days_remaining < 30) {
            indicator = 'orange';
            message = `⚠️ Contract expires in ${days_remaining} days`;
        } else {
            indicator = 'green';
            message = `✓ Active - ${days_remaining} days remaining`;
        }
    } else if (status === 'Expired') {
        indicator = 'red';
        message = '🔴 Contract Expired';
    } else if (status === 'Terminated') {
        indicator = 'red';
        message = '🔴 Contract Terminated';
    }

    frm.page.set_indicator(__(status), indicator);
}

frappe.ui.form.on('Service Ticket', {
    setup(frm) {
        set_ticket_filters(frm);
        frm.set_query("custom_applicant", function() {
    if (!frm.doc.custom_customer) {
        return {};
    }

    return {
        query: "maintenance_app.api.get_service_ticket_applicants",
        filters: {
            customer: frm.doc.custom_customer,
            branch: frm.doc.custom_client_branch
        }
    };
    });
    },

    /*onload(frm) {
        if (frm.is_new() && !frm.doc.custom_raised_by) {
            frm.set_value('custom_raised_by', frappe.session.user);
        }
    },*/

    onload(frm) {
    if (frm.is_new() && !frm.doc.custom_raised_by) {
        frm.set_value(
            "custom_raised_by",
            frappe.user.full_name() || frappe.session.user
        );
    }
    },

    before_save(frm) {
        if (!frm.doc.custom_raised_by) {
            frm.set_value(
                "custom_raised_by",
                frappe.user.full_name() || frappe.session.user
            );
        }
    },

    refresh(frm) {
        set_ticket_filters(frm);
        simplify_ticket_ui(frm);
        toggle_rework_fields(frm);
        toggle_hold_reason(frm);
        update_ticket_title(frm);
        show_ticket_status_banner(frm);
        add_smart_buttons(frm);
        toggle_ticket_tabs(frm);
        apply_ticket_type_filter(frm, false);
        apply_resolved_closed_locking(frm);
        toggle_affected_equipment_fields(frm);

        // New component architecture
        if (frm.doc.custom_target_component) {
            load_target_component_details(frm);
        }

        // For equipment-only ticket, show clean affected equipment name
        if (frm.doc.custom_target_equipment && !frm.doc.custom_target_component) {
            load_target_equipment_display(frm);
        }

        // Handle pre-filled customer (from web form route_options)
        if (frm.doc.custom_customer && !frm.doc.custom_service_type) {
            find_active_contract(frm);
        }

        // Handle pre-filled branch (load contacts)
        if (
            frm.doc.custom_client_branch &&
            (!frm.doc.custom_branch_contacts || !frm.doc.custom_branch_contacts.length) &&
            (!frm.doc.custom_head_office_contacts || !frm.doc.custom_head_office_contacts.length)
        ) {
            load_ticket_contacts(frm);
        }

        // Handle pre-filled equipment (load components + warranty)
        if (frm.doc.custom_target_equipment) {
            load_component_groups(frm);

            // NEW: Check warranty even on initial load (with small delay for data sync)
            setTimeout(function() {
                check_and_set_warranty_service_type(frm);
                load_equipment_warranty_status(frm);
            }, 100);
        }

        if (frm.doc.custom_component_group) {
            load_component_items(frm);
        }
    },

    custom_subject(frm) {
        update_ticket_title(frm);
    },

    custom_request_type(frm) {
        apply_ticket_type_filter(frm, true);
    },

    custom_customer(frm) {
        set_ticket_filters(frm);

        if (!frm._setting_from_equipment) {
            frm.set_value('custom_client_branch', '');
            frm.set_value('custom_target_equipment', '');

            if (frm.fields_dict.custom_target_component_name) {
                frm.set_value('custom_target_component_name', '');
            }

            if (frm.fields_dict.custom_parent_equipment) {
                frm.set_value('custom_parent_equipment', '');
            }

            clear_ticket_contacts(frm);
        }

        frm.set_value('custom_maintenance_contract', '');
        frm.set_value('custom_sla_rule', '');
        frm.set_value('custom_service_type', 'Billable');

        update_ticket_title(frm);
    },

    custom_client_branch(frm) {
        set_ticket_filters(frm);

        if (!frm._setting_from_equipment) {
            frm.set_value('custom_target_equipment', '');

            if (!frm.doc.custom_target_component && frm.fields_dict.custom_target_component_name) {
                frm.set_value('custom_target_component_name', '');
            }
        }

        load_ticket_contacts(frm);

        if (frm.doc.custom_customer) {
            find_active_contract(frm);
        }
    },

    custom_target_equipment(frm) {
        if (!frm.doc.custom_target_equipment) {
            frm.set_value('custom_service_type', 'Billable');

            if (!frm.doc.custom_target_component) {
                clear_component_selection(frm);

                if (frm.fields_dict.custom_target_component_name) {
                    frm.set_value('custom_target_component_name', '');
                }
            }

            update_ticket_title(frm);
            toggle_affected_equipment_fields(frm);
            return;
        }

        if (!frm.doc.custom_target_component) {
            clear_component_selection(frm);
        }

        frappe.db.get_value('Installed Equipment', frm.doc.custom_target_equipment, [
            'custom_parent_customer',
            'custom_branch',
            'custom_asset_name',
            'custom_display_name'
        ], function(asset) {
            if (!asset) return;

            frm._setting_from_equipment = true;

            let tasks = [];

            if (asset.custom_parent_customer) {
                tasks.push(frm.set_value('custom_customer', asset.custom_parent_customer));
            }

            if (asset.custom_branch) {
                tasks.push(frm.set_value('custom_client_branch', asset.custom_branch));
            }

            Promise.all(tasks).then(() => {
                load_ticket_contacts(frm);
                find_active_contract(frm);

                if (!frm.doc.custom_target_component) {
                    if (frm.fields_dict.custom_target_component_name) {
                        frm.set_value(
                            'custom_target_component_name',
                            asset.custom_display_name || asset.custom_asset_name || frm.doc.custom_target_equipment
                        );
                    }

                    if (frm.fields_dict.custom_parent_equipment) {
                        frm.set_value('custom_parent_equipment', '');
                    }

                    load_component_groups(frm);
                } else {
                    load_target_component_details(frm);
                }

                update_ticket_title(frm);
                toggle_affected_equipment_fields(frm);
                check_and_set_warranty_service_type(frm);
                load_equipment_warranty_status(frm);
                frm._setting_from_equipment = false;
            }).catch(() => {
                frm._setting_from_equipment = false;
            });
        });
    },

    custom_target_component(frm) {
        load_target_component_details(frm);
        toggle_affected_equipment_fields(frm);
    },

    custom_component_group(frm) {
        if (frm.doc.custom_target_component) {
            return;
        }

        clear_component_item_selection(frm);
        load_component_items(frm);
    },

    custom_component_item(frm) {
        load_component_details(frm);
    },

    custom_applicant(frm) {
        load_applicant_details(frm);
    },

    custom_is_rework(frm) {
        toggle_rework_fields(frm);
    }
});


const TICKET_TYPE_BY_REQUEST_TYPE = {
    "Breakdown": [
        "Repair",
        "Service",        
    ],

    "Maintenance Request": [
        "Preventive Maintenance",
        "Service",
        "Calibration",
        "Commissioning"
    ],

    "General Request": [
        "Installation",
        "Survey",
        "Training",
        "Audit",
        "Asset Relocation",
        "Config Change",
        "Swap",
        "Loan",
        "Service",
        "Incident Investigation"
    ]
};

const ALL_TICKET_TYPES = [
    "Service",
    "Repair",
    "Preventive Maintenance",
    "Installation",
    "Commissioning",
    "Survey",
    "Training",
    "Audit",
    "Incident Investigation",
    "Asset Relocation",
    "Config Change",
    "Calibration",
    "Swap",
    "Loan"
];

function apply_ticket_type_filter(frm, clear_invalid) {
    if (!frm.fields_dict.custom_ticket_type) {
        return;
    }

    let request_type = frm.doc.custom_request_type || "";
    let allowed = TICKET_TYPE_BY_REQUEST_TYPE[request_type] || ALL_TICKET_TYPES;

    frm.set_df_property(
        "custom_ticket_type",
        "options",
        allowed.join("\n")
    );

    frm.refresh_field("custom_ticket_type");

    if (
        clear_invalid &&
        frm.doc.custom_ticket_type &&
        !allowed.includes(frm.doc.custom_ticket_type)
    ) {
        frm.set_value("custom_ticket_type", "");
        frappe.show_alert({
            message: __("Ticket Type cleared because it is not valid for the selected Request Type."),
            indicator: "orange"
        });
    }
}


/* =========================
   SIMPLIFY UI
========================= */

function simplify_ticket_ui(frm) {
    [
        'custom_ticket_status',
        'custom_commercial_status',
        'custom_planning_status',
        'custom_hold_reason',
        'custom_primary_planning_ref',
        'custom_primary_mission_ref',
        'custom_service_type',
        'custom_maintenance_contract',
        'custom_sla_rule',
        'custom_sla_status',
        'custom_response_due',
        'custom_resolution_due',
        'custom_planning_required',
        'custom_work_type'
    ].forEach(function(fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, 'read_only', 1);
        }
    });

    [
        'custom_sla_status',
        'custom_response_due',
        'custom_resolution_due'
    ].forEach(function(fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, 'hidden', 1);
        }
    });

    if (frm.is_new()) {
        if (!frm.doc.custom_ticket_status) frm.set_value('custom_ticket_status', 'Open');
        if (!frm.doc.custom_planning_status) frm.set_value('custom_planning_status', 'Not Required');
        if (!frm.doc.custom_commercial_status) frm.set_value('custom_commercial_status', 'N/A');
    }
}

/* =========================
   TITLE
========================= */

function update_ticket_title(frm) {
    let subject = frm.doc.custom_subject || '';
    let affected = frm.doc.custom_target_component_name || '';

    if (!affected && frm.doc.custom_target_equipment) {
        affected = frm.doc.custom_target_equipment;
    }

    let title = [affected, subject].filter(Boolean).join(' - ');

    if (frm.fields_dict.custom_ticket_title && frm.doc.custom_ticket_title !== title) {
        frm.set_value('custom_ticket_title', title);
    }
}

/* =========================
   CONTACTS
========================= */

function clear_ticket_contacts(frm) {
    frm.clear_table('custom_branch_contacts');
    frm.clear_table('custom_head_office_contacts');

    frm.refresh_fields([
        'custom_branch_contacts',
        'custom_head_office_contacts'
    ]);
}

function load_ticket_contacts(frm) {
    clear_ticket_contacts(frm);

    if (!frm.doc.custom_client_branch) return;

    frappe.db.get_doc('Client Branch', frm.doc.custom_client_branch)
        .then(branch => {
            (branch.custom_branch_contacts || []).forEach(row => {
                let child = frm.add_child('custom_branch_contacts');

                child.custom_contact = row.custom_contact || '';
                child.custom_contact_role = row.custom_contact_role || '';
                child.custom_phone = row.custom_phone || '';
                child.custom_email = row.custom_email || '';
            });

            (branch.custom_head_office_contacts || []).forEach(row => {
                let child = frm.add_child('custom_head_office_contacts');

                child.custom_contact = row.custom_contact || '';
                child.custom_contact_role = row.custom_contact_role || '';
                child.custom_phone = row.custom_phone || '';
                child.custom_email = row.custom_email || '';
            });

            frm.refresh_fields([
                'custom_branch_contacts',
                'custom_head_office_contacts'
            ]);
        });
}

function load_applicant_details(frm) {
    if (!frm.doc.custom_applicant) {
        frm.set_value('custom_applicant_role', '');
        frm.set_value('custom_applicant_email', '');
        frm.set_value('custom_applicant_phone', '');
        return;
    }

    frappe.db.get_doc('Contact', frm.doc.custom_applicant).then(contact => {
        frm.set_value('custom_applicant_role', contact.designation || '');

        let email = '';
        let phone = '';

        if (contact.email_ids && contact.email_ids.length) {
            let primary_email = contact.email_ids.find(e => e.is_primary);
            email = primary_email ? primary_email.email_id : contact.email_ids[0].email_id;
        }

        if (contact.phone_nos && contact.phone_nos.length) {
            let primary_phone = contact.phone_nos.find(p => p.is_primary_mobile_no || p.is_primary_phone);
            phone = primary_phone ? primary_phone.phone : contact.phone_nos[0].phone;
        }

        frm.set_value('custom_applicant_email', email || '');
        frm.set_value('custom_applicant_phone', phone || '');
    });
}

/* =========================
   SMART BUTTONS
========================= */

function add_smart_buttons(frm) {
    if (frm.is_new()) return;

    frm.clear_custom_buttons();

    if (frm.doc.custom_ticket_status === 'Closed') {
        frm.add_custom_button(__('Open Rework Ticket'), function() {
            create_rework_ticket(frm);
        }, __('Next Step'));
    }

    if (frm.doc.custom_primary_planning_ref) {
        frm.add_custom_button(__('Open Planning'), function() {
            frappe.set_route('Form', 'Tech Planning', frm.doc.custom_primary_planning_ref);
        }, __('Actions'));
    }

    if (frm.doc.custom_primary_mission_ref) {
        frm.add_custom_button(__('Open Mission'), function() {
            frappe.set_route('Form', 'Tech Mission', frm.doc.custom_primary_mission_ref);
        }, frm.doc.custom_ticket_status === 'Resolved' || frm.doc.custom_ticket_status === 'Closed' ? __('Next Step') : __('Actions'));
    }

    if (
        frm.doc.custom_ticket_status !== "Closed" &&
        frm.doc.custom_ticket_status !== "Cancelled"
    ) {
        frm.add_custom_button(__('Create Remote Session'), function () {
            create_remote_session(frm);
        }, __('Create'));
    }

    if (frm.doc.custom_ticket_status === 'Cancelled') return;

    add_next_step_buttons(frm);
    add_commercial_buttons(frm);
}

/* =========================
   NEXT STEP BUTTONS
========================= */

function add_next_step_buttons(frm) {
    if (frm.doc.custom_ticket_status === 'Closed' || frm.doc.custom_ticket_status === 'Cancelled') {
        return;
    }

    if (frm.doc.custom_work_type !== 'Tech Mission') {
        frm.add_custom_button(__('Switch to Planned Visit'), function() {
            if (!validate_ticket_ready(frm)) return;

            frm.set_value('custom_work_type', 'Tech Mission');
            frm.set_value('custom_planning_required', 1);
            frm.set_value('custom_planning_status', 'Required');

            frm.save().then(() => frm.reload_doc());
        }, __('Next Step'));
    }

    if (frm.doc.custom_work_type !== 'Quick Intervention') {
        frm.add_custom_button(__('Switch to Direct Dispatch'), function() {
            if (!validate_ticket_ready(frm)) return;

            frm.set_value('custom_work_type', 'Quick Intervention');
            frm.set_value('custom_planning_required', 0);
            frm.set_value('custom_planning_status', 'Not Required');

            frm.save().then(() => frm.reload_doc());
        }, __('Next Step'));
    }

    if (frm.doc.custom_work_type === 'Quick Intervention') {
        frm.add_custom_button(__('Create New Mission'), function() {
            prompt_and_create_tech_mission(frm, null);
        }, __('Next Step'));
    }

    if (frm.doc.custom_work_type === 'Tech Mission' && !frm.doc.custom_primary_planning_ref) {
        frm.add_custom_button(__('Create Planning'), function() {
            create_tech_planning(frm);
        }, __('Next Step'));
    }

    if (frm.doc.custom_work_type === 'Tech Mission') {
        frm.add_custom_button(__('Create New Mission'), function() {
            prompt_and_create_tech_mission(frm, frm.doc.custom_primary_planning_ref || null);
        }, __('Next Step'));
    }
}

/* =========================
   COMMERCIAL BUTTONS
========================= */

function add_commercial_buttons(frm) {
    let cs = frm.doc.custom_commercial_status || '';
    let ts = frm.doc.custom_ticket_status || '';
    let is_done = ['Resolved', 'Closed'].includes(ts);

    /*
        CORE RULE:
        - Ticket Status = technical/work status.
        - Commercial Status = quote/invoice/payment status.
        - If Ticket is Resolved or Closed, commercial actions must NOT move it
          back to Under Review, On Hold, or Ready for Planning.
    */

    // Billable job with no commercial action yet.
    // Useful when work is done and RM decides to invoice directly.
    if (
        frm.doc.custom_service_type === 'Billable' &&
        ['', 'N/A', 'Covered'].includes(cs)
    ) {
        frm.add_custom_button(__('Mark To Invoice'), function() {
            update_ticket_status(frm, {
                custom_commercial_status: 'To be Invoiced'
            });
        }, __('Commercial'));
    }

    // Send to Quote.
    // If work is already done, keep Ticket Status as Resolved/Closed.
    if (
        ['', 'N/A', 'Covered', 'To be Invoiced', 'Ready for Planning'].includes(cs) &&
        ['Open', 'Under Review', 'Ready for Planning', 'Resolved', 'Closed'].includes(ts)
    ) {
        frm.add_custom_button(__('Send to Quote'), function() {
            let changes = {
                custom_commercial_status: 'To Quote'
            };

            if (!is_done) {
                changes.custom_ticket_status = 'Under Review';
                changes.custom_hold_reason = '';
            }

            update_ticket_status(frm, changes);
        }, __('Commercial'));
    }

    // Create Quotation.
    if (cs === 'To Quote') {
        frm.add_custom_button(__('Create Quotation'), function() {
            create_quotation_from_ticket(frm);
        }, __('Commercial'));
    }

    // Quote Approved.
    // Before work: move to Ready for Planning.
    // After work: move directly to To be Invoiced.
    if (cs === 'Quote Sent') {
        frm.add_custom_button(__('Mark Quote Approved'), function() {
            let done_now = ['Resolved', 'Closed'].includes(frm.doc.custom_ticket_status || '');

            let changes = {
                custom_commercial_status: done_now ? 'To be Invoiced' : 'Ready for Planning'
            };

            if (!done_now) {
                changes.custom_ticket_status = 'Ready for Planning';
                changes.custom_hold_reason = '';
            }

            update_ticket_status(frm, changes);
        }, __('Commercial'));
    }

    // Parts received.
    // Before work: Ready for Planning.
    // After work: To be Invoiced.
    if (frm.doc.custom_requires_parts && cs === 'Awaiting Parts') {
        frm.add_custom_button(__('Mark Parts Received'), function() {
            let done_now = ['Resolved', 'Closed'].includes(frm.doc.custom_ticket_status || '');

            let changes = {
                custom_commercial_status: done_now ? 'To be Invoiced' : 'Ready for Planning'
            };

            if (!done_now) {
                changes.custom_ticket_status = 'Ready for Planning';
                changes.custom_hold_reason = '';
            }

            update_ticket_status(frm, changes);
        }, __('Commercial'));
    }

    // Commercial decision after work or when RM needs to choose route.
    // Does not alter technical status if ticket is Resolved/Closed.
    if (
        ['To be Invoiced', 'To Quote', 'Quote Sent', 'Quote Approved', 'Ready for Planning'].includes(cs) ||
        (is_done && frm.doc.custom_service_type === 'Billable')
    ) {
        frm.add_custom_button(__('Commercial Decision'), function() {
            frappe.prompt([
                {
                    label: __('Decision'),
                    fieldname: 'decision',
                    fieldtype: 'Select',
                    options: 'Create Invoice\nSend to Quote\nMark To Invoice',
                    reqd: 1
                }
            ], function(values) {
                let done_now = ['Resolved', 'Closed'].includes(frm.doc.custom_ticket_status || '');

                if (values.decision === 'Create Invoice') {
                    create_sales_invoice_from_ticket(frm);
                    return;
                }

                if (values.decision === 'Send to Quote') {
                    let changes = {
                        custom_commercial_status: 'To Quote'
                    };

                    if (!done_now) {
                        changes.custom_ticket_status = 'Under Review';
                        changes.custom_hold_reason = '';
                    }

                    update_ticket_status(frm, changes);
                    return;
                }

                if (values.decision === 'Mark To Invoice') {
                    update_ticket_status(frm, {
                        custom_commercial_status: 'To be Invoiced'
                    });
                }
            }, __('Commercial Decision'), __('Continue'));
        }, __('Commercial'));
    }

    if (ts === 'Resolved') {
        frm.add_custom_button(__('Close Ticket'), function() {
            close_ticket(frm);
        }, __('Next Step'));
    }
}

/* =========================
   CREATE QUOTATION
========================= */

function create_quotation_from_ticket(frm) {
    frappe.prompt([
        {
            label: __('Quotation Type'),
            fieldname: 'quote_type',
            fieldtype: 'Select',
            options: [
                { label: __('Labour / Service Only'), value: 'Labour / Service Only' },
                { label: __('Requires Parts'), value: 'Requires Parts' }
            ],
            reqd: 1
        }
    ], function(values) {
        let requires_parts = values.quote_type === 'Requires Parts' ? 1 : 0;

        frappe.route_options = {
            quotation_to: 'Customer',
            party_name: frm.doc.custom_customer,
            customer: frm.doc.custom_customer,
            custom_service_ticket: frm.doc.name,
            custom_requires_parts: requires_parts,
            custom_branch: frm.doc.custom_client_branch,
            company: frm.doc.company || frappe.defaults.get_user_default('company')
        };

        frm.set_value('custom_requires_parts', requires_parts);
        frm.refresh_field('custom_requires_parts');

        if (frm.is_dirty()) {
            frm.save().then(() => {
                frappe.set_route('Form', 'Quotation', 'new-quotation');
            }).catch(() => {
                frappe.set_route('Form', 'Quotation', 'new-quotation');
            });
        } else {
            frappe.set_route('Form', 'Quotation', 'new-quotation');
        }
    }, __('Create Quotation'), __('Continue'));
}

/* =========================
   INVOICING & STATUS
========================= */

function create_sales_invoice_from_ticket(frm) {
    frappe.prompt([
        {
            label: 'Invoice Type',
            fieldname: 'invoice_type',
            fieldtype: 'Select',
            options: 'With Used Parts\nEmpty Invoice',
            reqd: 1
        }
    ], function(values) {
        if (values.invoice_type === 'Empty Invoice') {
            frappe.route_options = {
                customer: frm.doc.custom_customer,
                custom_service_ticket: frm.doc.name,
                custom_branch: frm.doc.custom_client_branch,
                company: frm.doc.company || frappe.defaults.get_user_default('company')
            };

            frappe.set_route('Form', 'Sales Invoice', 'new-sales-invoice');
            return;
        }

        frappe.call({
            method: 'maintenance_app.api.create_sales_invoice_from_service_ticket',
            args: {
                ticket_name: frm.doc.name
            },
            callback: function(r) {
                if (!r || !r.message || !r.message.sales_invoice) return;

                frappe.set_route('Form', 'Sales Invoice', r.message.sales_invoice);
            }
        });
    }, 'Create Sales Invoice', 'Continue');
}

function update_ticket_status(frm, values) {
    let current_status = frm.doc.custom_ticket_status || '';
    let technical_done = ['Resolved', 'Closed'].includes(current_status);

    // Commercial actions must never reopen or re-plan completed work.
    if (technical_done) {
        if (
            values.custom_ticket_status &&
            !['Resolved', 'Closed'].includes(values.custom_ticket_status)
        ) {
            delete values.custom_ticket_status;
        }

        [
            'custom_planning_status',
            'custom_planning_required',
            'custom_work_type',
            'custom_primary_planning_ref',
            'custom_primary_mission_ref'
        ].forEach(function(fieldname) {
            if (Object.prototype.hasOwnProperty.call(values, fieldname)) {
                delete values[fieldname];
            }
        });
    }

    Object.keys(values).forEach(function(fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_value(fieldname, values[fieldname]);
        }
    });

    frm.save().then(function() {
        frappe.show_alert({
            message: __('Ticket updated.'),
            indicator: 'green'
        });
    });
}

function close_ticket(frm) {
    frappe.prompt([
        {
            label: __('Closure Notes'),
            fieldname: 'closure_notes',
            fieldtype: 'Small Text',
            reqd: 1
        }
    ], function(values) {
        frm.set_value('custom_ticket_status', 'Closed');

        if (frm.fields_dict.custom_closure_notes) {
            frm.set_value('custom_closure_notes', values.closure_notes);
        }

        if (frm.fields_dict.custom_closed_date) {
            frm.set_value('custom_closed_date', frappe.datetime.now_datetime());
        }

        if (frm.fields_dict.custom_closed_by) {
            frm.set_value('custom_closed_by', frappe.session.user);
        }

        frm.save().then(() => {
            frappe.show_alert({
                message: __('Ticket closed.'),
                indicator: 'green'
            });
        });
    }, __('Close Ticket'), __('Close'));
}

/* =========================
   TECH PLANNING & MISSION
========================= */

function create_tech_planning(frm) {
    if (!validate_ticket_ready(frm)) return;

    let planning_doc = {
        doctype: 'Tech Planning',
        custom_subject: frm.doc.custom_subject || '',
        custom_service_ticket: frm.doc.name,
        custom_parent_customer: frm.doc.custom_customer,
        custom_branch: frm.doc.custom_client_branch,
        custom_asset: frm.doc.custom_target_equipment,

        custom_target_component_name: frm.doc.custom_target_component_name || '',
        custom_parent_equipment: frm.doc.custom_parent_equipment || '',

        custom_component_group: frm.doc.custom_component_group || '',
        custom_component_item: frm.doc.custom_component_item || '',
        custom_component_row_id: frm.doc.custom_component_row_id || '',
        custom_component_serial: frm.doc.custom_component_serial || '',
        custom_component_brand: frm.doc.custom_component_brand || '',
        custom_component_model: frm.doc.custom_component_model || '',

        custom_request_description: build_request_description(frm),
        custom_request_type: frm.doc.custom_request_type || '',
        custom_ticket_type: frm.doc.custom_ticket_type || '',
        custom_service_type: frm.doc.custom_service_type || '',
        custom_applicant: frm.doc.custom_applicant || '',
        custom_applicant_role: frm.doc.custom_applicant_role || '',
        custom_applicant_email: frm.doc.custom_applicant_email || '',
        custom_applicant_phone: frm.doc.custom_applicant_phone || '',
        custom_planning_status: 'Draft'
    };

    frappe.call({
        method: 'frappe.client.insert',
        args: {
            doc: planning_doc
        },
        callback: function(r) {
            if (!r.message) return;

            let planning_name = r.message.name;

            copy_planned_team_to_doc(frm, 'Tech Planning', planning_name, function() {
                copy_ticket_details_to_doc(frm, 'Tech Planning', planning_name, function() {
                    frm.set_value('custom_primary_planning_ref', planning_name);
                    frm.set_value('custom_planning_required', 1);
                    frm.set_value('custom_planning_status', 'Required');
                    frm.set_value('custom_ticket_status', 'Ready for Planning');

                    frm.save().then(() => {
                        frappe.set_route('Form', 'Tech Planning', planning_name);
                    });
                });
            });
        }
    });
}

