function prompt_and_create_tech_mission(frm, planning_name) {

    frappe.prompt([
        {
            label: __('Planned Start'),
            fieldname: 'planned_start',
            fieldtype: 'Datetime',
            reqd: 1
        },
        {
            label: __('Planned End'),
            fieldname: 'planned_end',
            fieldtype: 'Datetime',
            reqd: 1
        },
        {
            label: __('Vehicle'),
            fieldname: 'vehicle',
            fieldtype: 'Link',
            options: 'Vehicle'
        }

    ], function(values) {

        if (values.planned_end <= values.planned_start) {
            frappe.msgprint(__('Planned End must be after Planned Start.'));
            return;
        }

        create_tech_mission(
            frm,
            planning_name,
            values.planned_start,
            values.planned_end,
            values.vehicle
        );

    }, __('Plan Mission'), __('Create Mission'));

}

function create_tech_mission(
    frm,
    planning_name,
    planned_start,
    planned_end,
    vehicle
)
{
    if (!validate_ticket_ready(frm)) return;

    let mission_doc = {
        doctype: 'Tech Mission',
        custom_subject: frm.doc.custom_subject || '',
        custom_service_ticket: frm.doc.name,
        custom_tech_planning: planning_name || '',
        custom_parent_customer: frm.doc.custom_customer,
        custom_branch: frm.doc.custom_client_branch,
        custom_asset: frm.doc.custom_target_equipment,
        custom_target_component_name: frm.doc.custom_target_component_name || '',
        custom_parent_equipment: frm.doc.custom_parent_equipment || '',

        custom_component_group: frm.doc.custom_component_group || '',
        custom_component_item: frm.doc.custom_component_item || '',
        custom_component_row_id: frm.doc.custom_component_row_id || '',
        custom_component_serial: frm.doc.custom_component_serial || '',
        custom_component_brand: frm.doc.custom_component_brand || '',
        custom_component_model: frm.doc.custom_component_model || '',
        custom_ticket_type: frm.doc.custom_ticket_type || 'Service',
        custom_work_type: frm.doc.custom_work_type || 'Quick Intervention',
        custom_service_type: frm.doc.custom_service_type || 'Billable',
        custom_mission_status: 'Scheduled',
        custom_planned_starttime: planned_start || '',
        custom_planned_endtime: planned_end || '',
        custom_vehicle: vehicle || '',
        custom_request_description: build_request_description(frm),
        custom_applicant: frm.doc.custom_applicant || '',
        custom_applicant_role: frm.doc.custom_applicant_role || '',
        custom_applicant_email: frm.doc.custom_applicant_email || '',
        custom_applicant_phone: frm.doc.custom_applicant_phone || ''
    };

    frappe.call({
        method: 'frappe.client.insert',
        args: {
            doc: mission_doc
        },
        callback: function(r) {
            if (!r.message) return;

            let mission_name = r.message.name;
            //append_tech_mission_to_ticket(frm, mission_name, r.message);

            copy_planned_team_to_doc(frm, 'Tech Mission', mission_name, function() {
                copy_ticket_details_to_doc(frm, 'Tech Mission', mission_name, function() {
                    frm.set_value('custom_primary_mission_ref', mission_name);
                    frm.set_value('custom_ticket_status', 'Planned');

                    if (planning_name) {
                        frm.set_value('custom_primary_planning_ref', planning_name);
                        frm.set_value('custom_planning_status', 'Fully Planned');
                    } else {
                        frm.set_value('custom_planning_required', 0);
                        frm.set_value('custom_planning_status', 'Not Required');
                    }

                    frappe.call({
                        method: 'maintenance_app.api.create_todos_for_existing_mission',
                        args: {
                            mission_name: mission_name
                        },
                        callback: function() {
                        append_tech_mission_to_ticket(frm, mission_name, r.message);

                            frm.save().then(() => {
                                frappe.set_route('Form', 'Tech Mission', mission_name);
                            });
                        }
                    });
                });
            });
        }
    });
}

function create_remote_session(frm) {

