/* =========================
   EQUIPMENT COMPONENT SELECTION
   Source:
   Installed Equipment.custom_installed_components child table

   Required Service Ticket fields:
   custom_component_group   Select
   custom_component_item    Select
   custom_component_row_id  Data / Hidden
   custom_component_serial  Data / Read Only
   custom_component_brand   Data / Read Only
   custom_component_model   Data / Read Only
========================= */

function clear_component_selection(frm) {
    // Do not clear fields when using new Equipment Component flow
    if (frm.doc.custom_target_component) {
        return;
    }

    frm._component_cache = [];

    if (frm.fields_dict.custom_component_group) {
        frm.set_df_property('custom_component_group', 'options', '');
    }

    if (frm.fields_dict.custom_component_item) {
        frm.set_df_property('custom_component_item', 'options', '');
    }

    [
        'custom_component_group',
        'custom_component_item',
        'custom_component_row_id',
        'custom_component_serial',
        'custom_component_brand',
        'custom_component_model'
    ].forEach(fieldname => {
        if (frm.fields_dict[fieldname]) {
            frm.set_value(fieldname, '');
        }
    });
}

function clear_component_item_selection(frm) {
    // Do not clear fields when using new Equipment Component flow
    if (frm.doc.custom_target_component) {
        return;
    }

    frm._component_cache = [];

    if (frm.fields_dict.custom_component_item) {
        frm.set_df_property('custom_component_item', 'options', '');
    }

    [
        'custom_component_item',
        'custom_component_row_id',
        'custom_component_serial',
        'custom_component_brand',
        'custom_component_model'
    ].forEach(fieldname => {
        if (frm.fields_dict[fieldname]) {
            frm.set_value(fieldname, '');
        }
    });
}

function load_component_groups(frm) {
    // Old component group/item selector should not run for new Equipment Component tickets
    if (frm.doc.custom_target_component) {
        return;
    }

    if (!frm.fields_dict.custom_component_group) return;

    if (!frm.doc.custom_target_equipment) {
        clear_component_selection(frm);
        return;
    }

    frappe.call({
        method: 'maintenance_app.api.get_component_groups_for_equipment',
        args: {
            equipment_name: frm.doc.custom_target_equipment
        },
        callback: function(r) {
            let groups = r.message || [];

            frm.set_df_property(
                'custom_component_group',
                'options',
                [''].concat(groups).join('\n')
            );

            frm.refresh_field('custom_component_group');

            if (
                frm.doc.custom_component_group &&
                !groups.includes(frm.doc.custom_component_group)
            ) {
                clear_component_item_selection(frm);
                frm.set_value('custom_component_group', '');
            }
        }
    });
}

function load_component_items(frm) {
    // Old component item selector should not run for new Equipment Component tickets
    if (frm.doc.custom_target_component) {
        return;
    }

    if (!frm.fields_dict.custom_component_item) return;

    if (!frm.doc.custom_target_equipment || !frm.doc.custom_component_group) {
        clear_component_item_selection(frm);
        return;
    }

    frappe.call({
        method: 'maintenance_app.api.get_components_for_equipment_group',
        args: {
            equipment_name: frm.doc.custom_target_equipment,
            component_group: frm.doc.custom_component_group
        },
        callback: function(r) {
            let rows = r.message || [];

            frm._component_cache = rows;

            let options = rows.map(row => build_component_option_label(row));

            frm.set_df_property(
                'custom_component_item',
                'options',
                [''].concat(options).join('\n')
            );

            frm.refresh_field('custom_component_item');

            if (
                frm.doc.custom_component_item &&
                !options.includes(frm.doc.custom_component_item)
            ) {
                [
                    'custom_component_item',
                    'custom_component_row_id',
                    'custom_component_serial',
                    'custom_component_brand',
                    'custom_component_model'
                ].forEach(fieldname => {
                    if (frm.fields_dict[fieldname]) {
                        frm.set_value(fieldname, '');
                    }
                });
            }
        }
    });
}

function build_component_option_label(row) {
    return row.component_item || '';
}

function load_component_details(frm) {
    if (!frm.doc.custom_component_item || !frm._component_cache) {
        return;
    }

    let selected = frm._component_cache.find(row => {
        return build_component_option_label(row) === frm.doc.custom_component_item
            || row.component_item === frm.doc.custom_component_item;
    });

    if (!selected) {
        return;
    }

    if (frm.fields_dict.custom_component_row_id) {
        frm.set_value('custom_component_row_id', selected.row_id || '');
    }

    if (frm.fields_dict.custom_component_serial) {
        frm.set_value('custom_component_serial', selected.serial || '');
    }

    if (frm.fields_dict.custom_component_brand) {
        frm.set_value('custom_component_brand', selected.brand || '');
    }

    if (frm.fields_dict.custom_component_model) {
        frm.set_value('custom_component_model', selected.model || '');
    }
}


/* =========================
   RESOLVED / CLOSED FIELD LOCKING
========================= */

const RESOLUTION_EDITABLE_FIELDS = [
    "custom_resolution_details",
    "custom_resolution_detail",
    "custom_resolution_notes",
    "custom_resolution_summary",
    "custom_root_cause",
    "custom_corrective_action",
    "custom_preventive_action",
    "custom_resolved_by",
    "custom_resolved_date",
    "custom_closure_notes",
    "custom_closed_by",
    "custom_closed_date"
];

const ALWAYS_SYSTEM_READ_ONLY_FIELDS = [
    "custom_ticket_status",
    "custom_commercial_status",
    "custom_planning_status",
    "custom_hold_reason",
    "custom_primary_planning_ref",
    "custom_primary_mission_ref",
    "custom_service_type",
    "custom_maintenance_contract",
    "custom_sla_rule",
    "custom_sla_status",
    "custom_response_due",
    "custom_resolution_due",
    "custom_planning_required",
    "custom_work_type"
];

function apply_resolved_closed_locking(frm) {
    let status = frm.doc.custom_ticket_status || "";

    if (!["Resolved", "Closed"].includes(status)) {
        unlock_fields_after_reopen(frm);
        return;
    }

    let allow_resolution_edit = status === "Resolved";

    Object.keys(frm.fields_dict || {}).forEach(fieldname => {
        let field = frm.fields_dict[fieldname];

        if (!field || !field.df) {
            return;
        }

        if (["Section Break", "Column Break", "Tab Break", "HTML", "Button"].includes(field.df.fieldtype)) {
            return;
        }

        let is_resolution_field = RESOLUTION_EDITABLE_FIELDS.includes(fieldname);

        if (allow_resolution_edit && is_resolution_field) {
            frm.set_df_property(fieldname, "read_only", 0);
        } else {
            frm.set_df_property(fieldname, "read_only", 1);
        }
    });

    ALWAYS_SYSTEM_READ_ONLY_FIELDS.forEach(fieldname => {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, "read_only", 1);
        }
    });

    if (status === "Resolved") {
        frm.dashboard.set_headline(
            __("Ticket is Resolved. Only Resolution / Closure fields can be edited."),
            "green"
        );
    }

    if (status === "Closed") {
        frm.dashboard.set_headline(
            __("Ticket is Closed. Fields are locked."),
            "green"
        );
    }
}

function unlock_fields_after_reopen(frm) {
    Object.keys(frm.fields_dict || {}).forEach(fieldname => {
        let field = frm.fields_dict[fieldname];

        if (!field || !field.df) {
            return;
        }

        if (["Section Break", "Column Break", "Tab Break", "HTML", "Button"].includes(field.df.fieldtype)) {
            return;
        }

        frm.set_df_property(fieldname, "read_only", 0);
    });

    ALWAYS_SYSTEM_READ_ONLY_FIELDS.forEach(fieldname => {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, "read_only", 1);
        }
    });
}


/* =========================
   SUPPORT FUNCTIONS
========================= */


function validate_request_ticket_type(frm) {
    if (!frm.doc.custom_request_type || !frm.doc.custom_ticket_type) {
        return true;
    }

    let allowed = TICKET_TYPE_BY_REQUEST_TYPE[frm.doc.custom_request_type] || ALL_TICKET_TYPES;

    if (!allowed.includes(frm.doc.custom_ticket_type)) {
        frappe.msgprint(
            __("Ticket Type {0} is not valid for Request Type {1}. Allowed: {2}", [
                frm.doc.custom_ticket_type,
                frm.doc.custom_request_type,
                allowed.join(", ")
            ])
        );
        return false;
    }

    return true;
}

function validate_ticket_ready(frm) {
    if (!validate_request_ticket_type(frm)) {
        return false;
    }

    if (!frm.doc.custom_customer || !frm.doc.custom_client_branch || !frm.doc.custom_target_equipment) {
        frappe.msgprint(__('Please select Customer, Client Branch, and Target Equipment first.'));
        return false;
    }

    if (!frm.doc.custom_planned_team || !frm.doc.custom_planned_team.length) {
        frappe.msgprint(__('Please assign at least one technician in Planned Team before continuing.'));
        return false;
    }

    return true;
}

function build_request_description(frm) {
    let parts = [];

    if (frm.doc.custom_subject) {
        parts.push('Subject: ' + frm.doc.custom_subject);
    }

    if (frm.doc.custom_request_type) {
        parts.push('Request Type: ' + frm.doc.custom_request_type);
    }

    if (frm.doc.custom_ticket_type) {
        parts.push('Ticket Type: ' + frm.doc.custom_ticket_type);
    }

    if (frm.doc.custom_target_component_name || frm.doc.custom_component_group || frm.doc.custom_component_item) {
        parts.push(
            'Affected Equipment: ' +
            [
                frm.doc.custom_target_component_name || frm.doc.custom_component_item,
                frm.doc.custom_component_serial ? 'SN: ' + frm.doc.custom_component_serial : ''
            ].filter(Boolean).join(' - ')
        );

        if (frm.doc.custom_parent_equipment) {
            parts.push('Parent Equipment: ' + frm.doc.custom_parent_equipment);
        }
    }

    if (frm.doc.custom_description) {
        parts.push('Description:\n' + frm.doc.custom_description);
    }

    return parts.join('\n\n');
}

function set_ticket_filters(frm) {
    if (frm.fields_dict.custom_client_branch) {
        frm.set_query('custom_client_branch', () => ({
            filters: [
                ['Client Branch', 'custom_parent_customer', '=', frm.doc.custom_customer || '']
            ]
        }));
    }

    if (frm.fields_dict.custom_target_equipment) {
        frm.set_query('custom_target_equipment', () => ({
            filters: [
                ['Installed Equipment', 'custom_parent_customer', '=', frm.doc.custom_customer || ''],
                ['Installed Equipment', 'custom_branch', '=', frm.doc.custom_client_branch || '']
            ]
        }));
    }
}

function find_active_contract(frm) {
    if (!frm.doc.custom_customer) return;

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Maintenance Contract',
            filters: {
                custom_customer: frm.doc.custom_customer,
                custom_status: 'Active'
            },
            fields: [
                'name',
                'custom_contract_type',
                'custom_default_sla_rule',
                'custom_start_date',
                'custom_end_date'
            ]
        },
        callback: function(r) {
            let contracts = r.message || [];
            let today = frappe.datetime.get_today();

            contracts = contracts.filter(c =>
                (!c.custom_start_date || c.custom_start_date <= today) &&
                (!c.custom_end_date || c.custom_end_date >= today)
            );

            if (!contracts.length) {
                frm.set_value('custom_maintenance_contract', '');
                frm.set_value('custom_sla_rule', '');
                frm.set_value('custom_service_type', 'Billable');
                return;
            }

            let contract = contracts[0];

            frm.set_value('custom_maintenance_contract', contract.name);

            if (contract.custom_default_sla_rule) {
                frm.set_value('custom_sla_rule', contract.custom_default_sla_rule);
            }

            frm.set_value(
                'custom_service_type',
                contract.custom_contract_type === 'Warranty'
                    ? 'Warranty'
                    : contract.custom_contract_type === 'AMC'
                        ? 'AMC'
                        : 'Billable'
            );
        }
    });
}

function toggle_rework_fields(frm) {
    let is_rework = frm.doc.custom_is_rework ? 1 : 0;

    [
        'custom_original_ticket',
        'custom_rework_reason',
        'custom_rework_approved',
        'custom_rework_count'
    ].forEach(fieldname => {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, 'hidden', !is_rework);
        }
    });
}

function toggle_hold_reason(frm) {
    let on_hold = frm.doc.custom_ticket_status === 'On Hold';

