/* ============================================================
   FINAL WARRANTY / CONTRACT OVERRIDE - 2026-06-21
   Source of truth:
   1. Warranty coverage is checked on parent Installed Equipment.
   2. Maintenance Contract is taken from the parent Installed Equipment
      custom_maintenance_contract field only.
   3. If no active equipment warranty and no active equipment contract:
      Service Type = Billable.
============================================================ */

function reset_ticket_to_billable(frm) {
    if (frm.fields_dict.custom_warranty) {
        frm.set_value('custom_warranty', '');
    }

    if (frm.fields_dict.custom_maintenance_contract) {
        frm.set_value('custom_maintenance_contract', '');
    }

    if (frm.fields_dict.custom_sla_rule) {
        frm.set_value('custom_sla_rule', '');
    }

    if (frm.fields_dict.custom_service_type) {
        frm.set_value('custom_service_type', 'Billable');
    }
}

function find_active_contract(frm) {
    /*
        IMPORTANT:
        Do not auto-pick a random active customer contract anymore.
        For equipment/component tickets, contract must come from the parent Installed Equipment.
        This prevents Service Type staying as Warranty when the asset itself has no warranty/contract.
    */

    if (!frm.doc.custom_target_equipment) {
        reset_ticket_to_billable(frm);
        return;
    }

    frappe.db.get_value(
        'Installed Equipment',
        frm.doc.custom_target_equipment,
        [
            'custom_maintenance_contract',
            'custom_sla_rule'
        ],
        function(asset) {
            if (!asset || !asset.custom_maintenance_contract) {
                reset_ticket_to_billable(frm);
                return;
            }

            frappe.db.get_value(
                'Maintenance Contract',
                asset.custom_maintenance_contract,
                [
                    'name',
                    'custom_contract_type',
                    'custom_default_sla_rule',
                    'custom_start_date',
                    'custom_end_date',
                    'custom_status'
                ],
                function(contract) {
                    if (!contract || contract.custom_status !== 'Active') {
                        reset_ticket_to_billable(frm);
                        return;
                    }

                    let today = frappe.datetime.get_today();

                    if (
                        (contract.custom_start_date && contract.custom_start_date > today) ||
                        (contract.custom_end_date && contract.custom_end_date < today)
                    ) {
                        reset_ticket_to_billable(frm);
                        return;
                    }

                    frm.set_value('custom_maintenance_contract', contract.name);

                    frm.set_value(
                        'custom_sla_rule',
                        asset.custom_sla_rule || contract.custom_default_sla_rule || ''
                    );

                    let contract_type = contract.custom_contract_type || '';

                    if (contract_type === 'Warranty') {
                        frm.set_value('custom_service_type', 'Warranty');
                    } else if (contract_type === 'AMC') {
                        frm.set_value('custom_service_type', 'AMC');
                    } else if (contract_type) {
                        frm.set_value('custom_service_type', contract_type);
                    } else {
                        frm.set_value('custom_service_type', 'Billable');
                    }
                }
            );
        }
    );
}

function load_equipment_warranty_status(frm) {
    if (!frm.doc.custom_target_equipment) {
        frm.dashboard.clear_headline();
        reset_ticket_to_billable(frm);
        return;
    }

    frappe.call({
        method: 'maintenance_app.api.get_equipment_warranty_status',
        args: {
            equipment_name: frm.doc.custom_target_equipment
        },
        callback: function(r) {
            let warranty_info = r.message || {};

            if (warranty_info.is_covered) {
                let indicator_color = warranty_info.days_remaining > 30 ? 'green' : 'orange';

                frm.dashboard.set_headline(
                    `<span style="font-size: 13px;"><b>WARRANTY:</b> ${warranty_info.coverage_type || 'Covered'} - Expires in ${warranty_info.days_remaining || 0} days (${warranty_info.warranty_end_date || ''})</span>`,
                    indicator_color
                );

                if (frm.fields_dict.custom_warranty) {
                    frm.set_value('custom_warranty', warranty_info.warranty_name || '');
                }

                frappe.show_alert({
                    message: warranty_info.message || 'Equipment is under warranty.',
                    indicator: 'green'
                });
            } else {
                frm.dashboard.set_headline(
                    '<span style="font-size: 13px;"><b>WARRANTY:</b> No active warranty coverage</span>',
                    'red'
                );

                if (frm.fields_dict.custom_warranty) {
                    frm.set_value('custom_warranty', '');
                }

                // No warranty. Contract must be checked from the parent Installed Equipment.
                // If no active equipment contract, this will set Billable.
                find_active_contract(frm);
            }
        }
    });
}

function check_and_set_warranty_service_type(frm) {
    /*
        Single reliable entry point.
        Uses the same warranty API as the red/green banner, so Service Type
        cannot disagree with the banner anymore.
    */

    if (!frm.doc.custom_target_equipment) {
        reset_ticket_to_billable(frm);
        return;
    }

    frappe.call({
        method: 'maintenance_app.api.get_equipment_warranty_status',
        args: {
            equipment_name: frm.doc.custom_target_equipment
        },
        callback: function(r) {
            let warranty_info = r.message || {};

            if (warranty_info.is_covered) {
                if (frm.fields_dict.custom_warranty) {
                    frm.set_value('custom_warranty', warranty_info.warranty_name || '');
                }

                frm.set_value('custom_maintenance_contract', '');
                frm.set_value('custom_sla_rule', '');
                frm.set_value('custom_service_type', 'Warranty');

                frappe.show_alert({
                    message: warranty_info.message || '✓ Equipment under Warranty - Service type set to Warranty',
                    indicator: 'green'
                });

                return;
            }

            if (frm.fields_dict.custom_warranty) {
                frm.set_value('custom_warranty', '');
            }

            // No equipment warranty. Now check only the contract linked to the parent asset.
            // If none, find_active_contract() resets service type to Billable.
            find_active_contract(frm);
        }
    });
}

