/* =========================
   AUTO REFRESH COMPONENT SNAPSHOT
   Equipment Component = source of truth
   Installed Components table = display snapshot
========================= */

function refresh_component_snapshot(frm) {
    let rows = frm.doc.custom_installed_components || [];

    if (!rows.length) {
        return;
    }

    if (frm._refreshing_component_snapshot) {
        return;
    }

    frm._refreshing_component_snapshot = true;

    let promises = [];

    rows.forEach(function(row) {
        if (!row.custom_equipment_component) {
            return;
        }

        let p = frappe.db.get_doc('Equipment Component', row.custom_equipment_component)
            .then(function(component) {
                let changed = false;

                let serial = component.custom_serial_number || component.custom_serial || '';
                let status = component.custom_status || 'Installed';

                if (status === 'Active') {
                    status = 'Installed';
                }


                if ((row.custom_component_group || '') !== (component.custom_component_group || '')) {
                    row.custom_component_group = component.custom_component_group || '';
                    changed = true;
                }

                if ((row.custom_equipment_type || '') !== (component.custom_equipment_type || '')) {
                    row.custom_equipment_type = component.custom_equipment_type || '';
                    changed = true;
                }

                if ((row.custom_brand || '') !== (component.custom_make || '')) {
                    row.custom_brand = component.custom_make || '';
                    changed = true;
                }

                if ((row.custom_model || '') !== (component.custom_model || '')) {
                    row.custom_model = component.custom_model || '';
                    changed = true;
                }

                if ((row.custom_serial_number || '') !== serial) {
                    row.custom_serial_number = serial;
                    changed = true;
                }

                if ((row.custom_status || '') !== status) {
                    row.custom_status = status;
                    changed = true;
                }

                return changed;
            });

        promises.push(p);
    });

    Promise.all(promises).then(function(results) {
        let has_changes = results.some(function(x) {
            return x === true;
        });

        if (has_changes) {
            frm.refresh_field('custom_installed_components');

            frappe.show_alert({
                message: __('Component details refreshed from component master.'),
                indicator: 'blue'
            });
        }

        frm._refreshing_component_snapshot = false;
    }).catch(function() {
        frm._refreshing_component_snapshot = false;
    });
}


