function display_combined_ie_status_banner(frm) {
    if (frm.is_new() || !frm.doc.name) {
        return;
    }

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Warranty',
            filters: {
                custom_installed_equipment: frm.doc.name,
                custom_warranty_status: 'Active'
            },
            fields: [
                'name',
                'custom_warranty_title',
                'custom_warranty_end_date',
                'custom_coverage_type'
            ],
            order_by: 'custom_warranty_end_date asc',
            limit_page_length: 0
        },
        callback: function(r) {
            let warranties = r.message || [];
            let warranty_html = '';
            let banner_color = 'blue';

            if (warranties.length > 0) {
                let today = frappe.datetime.get_today();

                let active_warranties = warranties.filter(function(w) {
                    return w.custom_warranty_end_date && w.custom_warranty_end_date >= today;
                });

                if (active_warranties.length > 0) {
                    let earliest = active_warranties[0];

                    let end_parts = earliest.custom_warranty_end_date.split('-');
                    let today_parts = today.split('-');

                    let end_date = new Date(end_parts[0], end_parts[1] - 1, end_parts[2]);
                    let today_date = new Date(today_parts[0], today_parts[1] - 1, today_parts[2]);

                    let days_remaining = Math.ceil((end_date - today_date) / (1000 * 60 * 60 * 24));

                    if (days_remaining < 7) {
                        banner_color = 'red';
                    } else if (days_remaining < 30) {
                        banner_color = 'orange';
                    } else {
                        banner_color = 'green';
                    }

                    let warranty_count = active_warranties.length;
                    let count_text = warranty_count > 1 ? `${warranty_count} active warranties` : '1 active warranty';

                    warranty_html = `
                        <span style="color: inherit; font-weight: bold;">WARRANTY:</span>
                        ${count_text} - ${earliest.custom_coverage_type || ''} -
                        Expires in ${days_remaining} days (${earliest.custom_warranty_end_date})
                    `;
                } else {
                    banner_color = 'red';
                    warranty_html = '<span style="color: inherit; font-weight: bold;">WARRANTY:</span> All warranties expired';
                }
            } else {
                warranty_html = '<span style="color: inherit; font-weight: bold;">WARRANTY:</span> No active warranty';
            }

            let headline = `
                <div style="line-height: 1.6;">
                    <div>
                        <span style="color: inherit; font-weight: bold;">OPERATIONAL:</span>
                        Fields locked. Use interventions for operational changes.
                    </div>
                    <div style="margin-top: 8px; border-top: 1px solid rgba(0,0,0,0.1); padding-top: 8px;">
                        ${warranty_html}
                    </div>
                </div>
            `;

            frm.dashboard.set_headline(headline, banner_color);
        }
    });
}


