/* =========================
   NEXT MAINTENANCE DATE
========================= */

function calculate_next_maintenance_date(frm) {
    if (!frm.doc.custom_last_service_date || !frm.doc.custom_maint_frequency) {
        return;
    }

    let last_service = moment(frm.doc.custom_last_service_date);
    let next_date;

    switch(frm.doc.custom_maint_frequency) {
        case 'Monthly':
            next_date = last_service.add(1, 'month').format('YYYY-MM-DD');
            break;
        case 'Quarterly':
            next_date = last_service.add(3, 'months').format('YYYY-MM-DD');
            break;
        case 'Bi-Annual':
            next_date = last_service.add(6, 'months').format('YYYY-MM-DD');
            break;
        case 'Annual':
            next_date = last_service.add(1, 'year').format('YYYY-MM-DD');
            break;
        default:
            next_date = null;
    }

    if (next_date && frm.fields_dict.custom_next_maintenance_date) {
        frm.set_value('custom_next_maintenance_date', next_date);
    }
}


