========================= */

function setup_mi_form(frm) {
    set_mi_filters(frm);
    toggle_lock_state(frm);
    toggle_intervention_fields(frm);
    toggle_component_replacement_fields(frm);
    toggle_config_changes_access(frm);
    lock_ratings_if_confirmed(frm);
    calculate_hours(frm);
    update_checkout_status(frm);

    if (frm.doc.docstatus === 1) {
        frm.page.clear_custom_buttons();
        frm.page.clear_primary_action();
        frm.dashboard.set_headline(__('This intervention is submitted.'), 'blue');
        return;
    }

    if (frm.fields_dict.custom_parts_table) {
        frm.fields_dict.custom_parts_table.grid.get_field('custom_item_code').get_query = function() {
            return {
                filters: {
                    is_stock_item: 1,
                    disabled: 0
                }
            };
        };
    }

    setup_check_buttons(frm);
}

function toggle_lock_state(frm) {
    let checked_in = !!frm.doc.custom_start_time;
    let submitted = frm.doc.docstatus === 1;

    let lock = !checked_in || submitted;

    let fields = [
        'custom_intervention_type',
        'custom_work_progress',
        'custom_work_outcome',
        'custom_billing_analysis',
        'custom_new_branch',
        'custom_removed_asset_outcome',
        'custom_company_workshop',
        'custom_new_make',
        'custom_loan_required',
        'custom_new_serial',
        'custom_new_asset',
        'custom_new_model',
        'custom_parts_table',
        'custom_config_changes',
        'custom_client_signature',
        'custom_tech_signature',
        'custom_signatory_name',
        'custom_quality_score',
        'custom_hse_score',
        'custom_completed_time',
        'custom_client_signed_time',
        'custom_client_signature_received',
        'custom_checkout_status',
        'custom_component_replaced',
        'custom_equipment_component',
        'custom_new_equipment_component',
        'custom_new_component_item',
        'custom_new_component_serial',
        'custom_new_component_brand',
        'custom_new_component_model',
        'custom_component_replacement_reason'
    ];

    fields.forEach(function(fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, 'read_only', lock ? 1 : 0);
        }
    });

    lock_ratings_if_confirmed(frm);
}

function show_complete_work_dialog(frm) {
    let dialog = new frappe.ui.Dialog({
        title: __('Complete Work'),
        fields: [
            {
                label: __('Final Outcome'),
                fieldname: 'outcome',
                fieldtype: 'Select',
                options: [
                    'Work Completed',
                    'Continue Work',
                    'Waiting for Parts',
                    'Waiting for Client',
                    'To Quote (Billable)',
                    'Could Not Complete',
                    'False Call Out'
                ].join('\n'),
                default: frm.doc.custom_work_outcome || '',
                reqd: 1
            },
            {
                /*label: __('Fault Type'),
                fieldname: 'fault_type',
                fieldtype: 'Link',
                options: 'Fault Type',
                default: frm.doc.custom_fault_type || '',
                reqd: 1*/

                 label: __('Fault Type'),
                fieldname: 'fault_type',
                fieldtype: 'Link',
                options: 'Fault Type',
                default: frm.doc.custom_fault_type || '',
                reqd: frm.doc.custom_intervention_type === 'Repair' ? 1 : 0
            },
            {
                label: __('Technical Progress Notes'),
                fieldname: 'notes',
                fieldtype: 'Small Text',
                default: frm.doc.custom_work_progress || '',
                reqd: 1
            }
        ],
        primary_action_label: __('Complete Work'),
        primary_action(values) {
            frm.set_value('custom_work_outcome', values.outcome);
            frm.set_value('custom_fault_type', values.fault_type);
            frm.set_value('custom_work_progress', values.notes);

            if (!frm.doc.custom_completed_time) {
                frm.set_value('custom_completed_time', frappe.datetime.now_datetime());
            }

            frm.set_value('custom_checkout_status', 'Work Completed');

            dialog.hide();

            frm.save().then(() => {
                frm.reload_doc().then(() => {
                    toggle_lock_state(frm);
                    toggle_intervention_fields(frm);
                    toggle_config_changes_access(frm);
                    setup_check_buttons(frm);

                    frappe.show_alert({
                        message: __('Work Completed'),
                        indicator: 'green'
                    });
                });
            });
        }
    });

    dialog.show();
}

function mark_client_signed(frm) {
    let missing = [];

    if (!frm.doc.custom_signatory_name) {
        missing.push(__('Signatory Name'));
    }

    if (!frm.doc.custom_client_signature) {
        missing.push(__('Client Signature'));
    }

    if (!frm.doc.custom_tech_signature) {
        missing.push(__('Technician Signature'));
    }

    /*if (!frm.doc.custom_quality_score) {
        missing.push(__('Quality Rating'));
    }

    if (!frm.doc.custom_hse_score) {
        missing.push(__('HSE Rating'));
    }*/

    if (frm.doc.custom_work_outcome === "Work Completed") {
    if (!frm.doc.custom_quality_score) {
        missing.push(__('Quality Rating'));
    }

    if (!frm.doc.custom_hse_score) {
        missing.push(__('HSE Rating'));
    }
    }

    if (missing.length) {
        frappe.msgprint(__('Please complete before marking client signed: {0}', [missing.join(', ')]));
        return;
    }

    frm.set_value('custom_client_signature_received', 1);

    if (!frm.doc.custom_client_signed_time) {
        frm.set_value('custom_client_signed_time', frappe.datetime.now_datetime());
    }

    frm.set_value('custom_checkout_status', 'Client Signed');

    frm.save().then(() => {
        frm.reload_doc().then(() => {
            setup_check_buttons(frm);

            frappe.show_alert({
                message: __('Client Signature Confirmed'),
                indicator: 'green'
            });
        });
    });
}

function final_check_out(frm) {
    if (!frm.doc.custom_completed_time) {
        frappe.msgprint(__('Please Complete Work before Check Out.'));
        return;
    }

    if (!frm.doc.custom_client_signature_received) {
        frappe.msgprint(__('Please mark Client Signed before Check Out.'));
        return;
    }

    frm.set_value('custom_end_time', frappe.datetime.now_datetime());
    frm.set_value('custom_checkout_status', 'Checked Out');

    calculate_hours(frm);

    frm.save().then(() => {
        frm.reload_doc().then(() => {
            setup_check_buttons(frm);

            frappe.show_alert({
                message: __('Checked Out'),
                indicator: 'green'
            });
        });
    });
}

function setup_check_buttons(frm) {
    if (frm.is_new() || frm.doc.docstatus !== 0) {
        return;
    }

    frm.page.clear_primary_action();
    frm.page.clear_actions_menu();

    if (!frm.doc.custom_start_time) {
        frm.page.set_primary_action(__('Check In'), function() {
            frm.set_value('custom_start_time', frappe.datetime.now_datetime());
            frm.set_value('custom_start_date', frappe.datetime.get_today());
            frm.set_value('custom_checkout_status', 'Checked In');

            frm.save().then(() => {
                frm.reload_doc().then(() => {
                    toggle_lock_state(frm);
                    toggle_intervention_fields(frm);
                    toggle_config_changes_access(frm);
                    setup_check_buttons(frm);

                    frappe.show_alert({
                        message: __('Checked In'),
                        indicator: 'green'
                    });
                });
            });
        });

        return;
    }

    if (frm.doc.custom_start_time && !frm.doc.custom_completed_time) {
        frm.page.set_primary_action(__('Complete Work'), function() {
            show_complete_work_dialog(frm);
        });

        return;
    }

    if (frm.doc.custom_completed_time && !frm.doc.custom_client_signature_received) {
        frm.page.set_primary_action(__('Mark Client Signed'), function() {
            mark_client_signed(frm);
        });

        frm.page.add_action_item(__('Edit Work Outcome'), function() {
            show_complete_work_dialog(frm);
        });

        return;
    }

    if (frm.doc.custom_client_signature_received && !frm.doc.custom_end_time) {
        frm.page.set_primary_action(__('Check Out'), function() {
            final_check_out(frm);
        });

        frm.page.add_action_item(__('Edit Work Outcome'), function() {
            show_complete_work_dialog(frm);
        });

        return;
    }

    if (
        frm.doc.custom_start_time &&
        frm.doc.custom_completed_time &&
        frm.doc.custom_client_signature_received &&
        frm.doc.custom_end_time
    ) {
        frm.page.set_primary_action(__('Submit'), function() {
            frm.savesubmit();
        });
    }
}

function update_checkout_status(frm) {
    if (!frm.fields_dict.custom_checkout_status || frm.doc.docstatus === 1) {
        return;
    }

    let status = 'Not Started';

    if (frm.doc.custom_end_time) {
        status = 'Checked Out';
    } else if (frm.doc.custom_client_signature_received) {
        status = 'Client Signed';
    } else if (frm.doc.custom_completed_time) {
        status = 'Work Completed';
    } else if (frm.doc.custom_start_time) {
        status = 'Checked In';
    }

    if (frm.doc.custom_checkout_status !== status) {
        frm.set_value('custom_checkout_status', status);
    }
}

