function calculate_hours(frm) {
    if (!frm.doc.custom_start_time || !frm.doc.custom_end_time) return;

    let start = moment(frm.doc.custom_start_time);
    let end = moment(frm.doc.custom_end_time);
    let diff = end.diff(start, 'minutes');

    if (diff <= 0) return;

    frm.set_value('custom_hours_worked', flt(diff / 60, 2));
}

function set_config_datetime(cdt, cdn) {
    let row = locals[cdt][cdn];

    if (!row.custom_config_datetime) {
        frappe.model.set_value(
            cdt,
            cdn,
            'custom_config_datetime',
            frappe.datetime.now_datetime()
        );
    }
}

function validate_before_submit(frm) {
    if (!frm.doc.custom_start_time) {
        frappe.throw(__('Please Check In before submitting.'));
    }

    if (!frm.doc.custom_completed_time) {
        frappe.throw(__('Please Complete Work before submitting.'));
    }

    if (!frm.doc.custom_work_outcome) {
        frappe.throw(__('Work Outcome is required.'));
    }

    if (!frm.doc.custom_work_progress) {
        frappe.throw(__('Technical Progress Notes are required.'));
    }

    if (!frm.doc.custom_client_signature_received) {
        frappe.throw(__('Please mark Client Signed before submitting.'));
    }

    if (!frm.doc.custom_client_signed_time) {
        frappe.throw(__('Client Signed Time is required.'));
    }

    if (!frm.doc.custom_end_time) {
        frappe.throw(__('Please Check Out before submitting.'));
    }

    /*frm.set_value('custom_checkout_status', 'Submitted');*/
}

function lock_ratings_if_confirmed(frm) {
    if (frm.doc.custom_quality_score && frm.doc.custom_hse_score) {
        frm.set_df_property('custom_quality_score', 'read_only', 1);
        frm.set_df_property('custom_hse_score', 'read_only', 1);
    }
}

function confirm_and_lock_ratings(frm) {
    if (
        frm.doc.custom_quality_score &&
        frm.doc.custom_hse_score &&
        !frm.doc.__ratings_confirmed
    ) {
        frappe.confirm(__('Confirm ratings? They will be locked.'), function() {
            frm.doc.__ratings_confirmed = true;
            frm.set_df_property('custom_quality_score', 'read_only', 1);
            frm.set_df_property('custom_hse_score', 'read_only', 1);
        });
    }
}

function set_mi_filters(frm) {
    if (frm.fields_dict.custom_new_branch) {
        frm.set_query("custom_new_branch", function() {
            if (!frm.doc.custom_parent_customer) {
                return {};
            }

            return {
                filters: {
                    custom_parent_customer: frm.doc.custom_parent_customer
                }
            };
        });
    }

    if (frm.fields_dict.custom_new_asset) {
        frm.set_query("custom_new_asset", function() {
            let filters = {};

            if (frm.doc.custom_asset) {
                filters.name = ["!=", frm.doc.custom_asset];
            }

            // For a same-site position swap, only equipment installed at
            // the current customer branch may be selected.
            if (
                frm.doc.custom_intervention_type === "Swap" &&
                frm.doc.custom_removed_asset_outcome === "Swapped Within Same Site"
            ) {
                if (frm.doc.custom_parent_customer) {
                    filters.custom_parent_customer =
                        frm.doc.custom_parent_customer;
                }

                if (frm.doc.custom_branch) {
                    filters.custom_branch = frm.doc.custom_branch;
                }

                filters.custom_asset_status = "Installed";
            }

            return {
                filters: filters
            };
        });
    }

    if (frm.fields_dict.custom_company_workshop) {
        frm.set_query("custom_company_workshop", function() {
            return {};
        });
    }

    if (frm.fields_dict.custom_equipment_component) {
        frm.set_query("custom_equipment_component", function() {
            if (!frm.doc.custom_asset) {
                return {};
            }

            return {
                filters: {
                    custom_parent_equipment: frm.doc.custom_asset
                }
            };
        });
    }

    if (frm.fields_dict.custom_new_equipment_component) {
        frm.set_query("custom_new_equipment_component", function() {
            let filters = [];

            if (frm.doc.custom_equipment_component) {
                filters.push([
                    "Equipment Component",
                    "name",
                    "!=",
                    frm.doc.custom_equipment_component
                ]);
            }

            filters.push([
                "Equipment Component",
                "custom_status",
                "in",
                ["Installed", "Repaired"]
            ]);

            return {
                filters: filters
            };
        });
    }
}


function fetch_component_snapshot(frm, is_new_component) {
    let link_field = is_new_component
        ? "custom_new_equipment_component"
        : "custom_equipment_component";

    let component_name = frm.doc[link_field];

    let target_fields = is_new_component
        ? {
            item: "custom_new_component_item",
            serial: "custom_new_component_serial",
            brand: "custom_new_component_brand",
            model: "custom_new_component_model"
        }
        : {
            item: "custom_component_item",
            serial: "custom_component_serial",
            brand: "custom_component_brand",
            model: "custom_component_model"
        };

    if (!component_name) {
        Object.keys(target_fields).forEach(function(key) {
            let fieldname = target_fields[key];

            if (frm.fields_dict[fieldname]) {
                frm.set_value(fieldname, "");
            }
        });

        return;
    }

    frappe.db.get_value(
        "Equipment Component",
        component_name,
        [
            "custom_component_item",
            "custom_equipment_type",
            "custom_serial_number",
            "custom_serial",
            "custom_make",
            "custom_brand",
            "custom_model"
        ],
        function(r) {
            if (!r) {
                return;
            }

            let item_value =
                r.custom_component_item ||
                r.custom_equipment_type ||
                "";

            let serial_value =
                r.custom_serial_number ||
                r.custom_serial ||
                "";

            let brand_value =
                r.custom_make ||
                r.custom_brand ||
                "";

            if (frm.fields_dict[target_fields.item]) {
                frm.set_value(target_fields.item, item_value);
            }

            if (frm.fields_dict[target_fields.serial]) {
                frm.set_value(target_fields.serial, serial_value);
            }

            if (frm.fields_dict[target_fields.brand]) {
                frm.set_value(target_fields.brand, brand_value);
            }

            if (frm.fields_dict[target_fields.model]) {
                frm.set_value(target_fields.model, r.custom_model || "");
            }
        }
    );
}


function fetch_current_asset_position(frm) {
    if (!frm.doc.custom_asset) return;
    if (!frm.fields_dict.custom_current_site_position) return;

    frappe.db.get_value(
        "Installed Equipment",
        frm.doc.custom_asset,
        ["custom_site_id"],
        function(r) {
            if (!r) return;
            frm.set_value(
                "custom_current_site_position",
                r.custom_site_id || ""
            );
        }
    );
}

function fetch_replacement_asset_details(frm) {
    if (!frm.doc.custom_new_asset) return;

    frappe.db.get_value(
        "Installed Equipment",
        frm.doc.custom_new_asset,
        ["custom_asset_id", "custom_make", "custom_model", "custom_branch", "custom_site_id"],
        function(r) {
            if (!r) return;

            frm.set_value("custom_new_serial", r.custom_asset_id || "");
            frm.set_value("custom_new_make", r.custom_make || "");
            frm.set_value("custom_new_model", r.custom_model || "");

            if (frm.fields_dict.custom_replacement_site_position) {
                frm.set_value(
                    "custom_replacement_site_position",
                    r.custom_site_id || ""
                );
            }

            // The replacement equipment is installed at the MI's current branch.
            // Destination Branch is reserved for the outgoing equipment.
            if (
                frm.doc.custom_intervention_type === "Swap" &&
                frm.doc.custom_removed_asset_outcome !== "Installed at Another Site"
            ) {
                frm.set_value("custom_new_branch", "");
            }
        }
    );
}


function add_change_component_button(frm) {

    if (frm.is_new() || frm.doc.docstatus !== 0) return;
    if (!frm.doc.custom_asset) return;

    frm.add_custom_button('Change Component', function() {

        frappe.call({
            method: "maintenance_app.api.get_components_for_equipment_group",
            args: {
                equipment_name: frm.doc.custom_asset,
                component_group: ""
            },
            freeze: true,
            freeze_message: 'Loading installed components...',
            callback: function(r) {
                let components = r.message || [];

                if (!components.length) {
                    frappe.msgprint('No installed components found for this equipment.');
                    return;
                }

                let option_map = {};

                let options = components.map(function(c) {
                    let label = c.component_item || c.component_group || c.row_id;

                    if (c.serial) {
                        label += " - SN: " + c.serial;
                    }

                    option_map[label] = c;
                    return label;
                });

                frappe.prompt([
                    {
                        label: 'Actual Component',
                        fieldname: 'actual_component_label',
                        fieldtype: 'Select',
                        options: options.join('\n'),
                        reqd: 1
                    },
                    {
                        label: 'Reason',
                        fieldname: 'reason',
                        fieldtype: 'Small Text',
                        reqd: 1
                    }
                ], function(values) {

                    let selected = option_map[values.actual_component_label];

                    if (!selected || !selected.row_id) {
                        frappe.msgprint('Selected component is invalid.');
                        return;
                    }

                    frappe.call({
                        method: "maintenance_app.api.change_mi_component",
                        args: {
                            mi_name: frm.doc.name,
                            component_row_id: selected.row_id,
                            reason: values.reason
                        },
                        freeze: true,
                        freeze_message: 'Changing component...',
                        callback: function(r) {
                            frm.reload_doc();
                        }
                    });

                }, 'Change Component', 'Update');
            }
        });

    }, 'Actions');
}

