frappe.ui.form.on('HSE Incident Report', {
    refresh(frm) {

        if (frm.is_new()) return;

        if (frm.doc.custom_incident_status === "Open") {

            frm.add_custom_button(__('Close Incident'), function () {

                frappe.confirm(
                    "Close this incident?",
                    function () {

                        frm.set_value("custom_incident_status", "Closed");

                        frm.save().then(() => {
                            frappe.show_alert({
                                message: "Incident Closed",
                                indicator: "green"
                            });
                        });

                    }
                );

            }, __('Actions'));

        }

        // Lock after closure
        if (frm.doc.custom_incident_status === "Closed") {
            frm.disable_form();
        }

        if (frm.doc.custom_incident_status === "Open") {

            frm.add_custom_button(__("Create Investigation"), function () {

                frappe.confirm("Create investigation ticket for this incident?", function () {

                    frappe.call({
                        method: "maintenance_app.api.create_investigation_ticket",
                        args: {
                            hse_report_name: frm.doc.name
                        },
                        callback: function (r) {
                            if (r.message && r.message.ticket) {
                                frappe.show_alert({
                                    message: "Investigation Ticket Created",
                                    indicator: "green"
                                });

                                frm.reload_doc();

                                frappe.set_route("Form", "Service Ticket", r.message.ticket);
                            }
                        }
                    });

                });

            }, __("Actions"));

        }

    }
});

